// Packaging tests for the container's env delivery and compose hygiene (#97).
//
// These read docker-compose.yml / .env.example / package.json as TEXT — no YAML parser, no new
// dependency. The original defect was invisible to every runtime test precisely because it lived in
// the packaging: PCI_MASTER_KEY was honoured by the code, documented in the runbooks, and never
// delivered to the container, so every Docker user silently landed on an autogenerated key.
//
// Every slice below is GUARDED with a landmark assertion first, so a compose refactor that moves or
// renames a service fails loudly here instead of passing vacuously against an empty string.

import { describe, it, expect } from "vitest";
import { readFileSync, readdirSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { join } from "node:path";

/**
 * Every SHIPPING `.ts` file under src/, concatenated — the corpus the host-only gate below greps.
 *
 * Test/fixture/conformance modules are excluded on purpose, twice over: they are not the gateway (a
 * name only a test reads is not "read by the gateway"), and including them makes the gate grade its
 * own homework — the hostOnly array below lives in a test file, so every quoted name in it would
 * match itself and the gate would flag all five entries.
 */
function readSrcTree(): string {
  const root = fileURLToPath(new URL("../", import.meta.url));
  const out: string[] = [];
  const walk = (dir: string): void => {
    for (const e of readdirSync(dir, { withFileTypes: true })) {
      const p = join(dir, e.name);
      if (e.isDirectory()) walk(p);
      else if (/\.(test|fixtures|conformance)\.ts$/.test(e.name)) continue;
      else if (e.name.endsWith(".ts")) out.push(readFileSync(p, "utf8"));
    }
  };
  walk(root);
  return out.join("\n");
}

/**
 * Does the gateway's own code read this environment variable? TWO forms, and the second is the one
 * that matters.
 *
 * `process.env.NAME` is the direct read. But the OAuth client secrets are read through a COMPUTED
 * key — `process.env[def.clientSecretEnv]`, with the actual names sitting as string literals in the
 * PROVIDERS table (src/oauth/providers.ts) — and so are several config values, which go through
 * `envOrUndefined("NAME")`. A gate that only greps the dotted form declares those variables
 * unread, which makes hostOnly a way to wave a genuinely-undelivered secret through with the suite
 * green: exactly the #97 shape this whole file exists to prevent. Matching the QUOTED NAME anywhere
 * in shipping source covers every indirection at once, and over-matching is the safe direction —
 * a false positive means someone has to justify a hostOnly entry, not that a secret silently stops
 * being delivered.
 */
function readByGateway(name: string, corpus: string): boolean {
  return corpus.includes(`process.env.${name}`) || new RegExp(`["'\`]${name}["'\`]`).test(corpus);
}

const compose = readFileSync(new URL("../../docker-compose.yml", import.meta.url), "utf8");
const envExample = readFileSync(new URL("../../.env.example", import.meta.url), "utf8");
const packageJson = readFileSync(new URL("../../package.json", import.meta.url), "utf8");

/** The `services:` block only — so top-level `volumes:` entries are never mistaken for services. */
function servicesBlock(): string {
  const lines = compose.split("\n");
  const start = lines.findIndex((l) => /^services:\s*$/.test(l));
  if (start < 0) throw new Error("docker-compose.yml has no top-level `services:` block");
  let end = lines.length;
  for (let i = start + 1; i < lines.length; i++) {
    if (/^\S/.test(lines[i])) {
      end = i;
      break;
    }
  }
  return lines.slice(start + 1, end).join("\n");
}

/** Every service name declared under `services:`. */
function serviceNames(): string[] {
  return [...servicesBlock().matchAll(/^ {2}(\S+):\s*$/gm)].map((m) => m[1]);
}

/** The text of one service, from `  <name>:` to the next `  <something>:` (or the block's end). */
function serviceSlice(name: string): string {
  const block = servicesBlock().split("\n");
  const start = block.findIndex((l) => l === `  ${name}:`);
  if (start < 0) throw new Error(`docker-compose.yml has no service named '${name}'`);
  let end = block.length;
  for (let i = start + 1; i < block.length; i++) {
    if (/^ {2}\S+:\s*$/.test(block[i])) {
      end = i;
      break;
    }
  }
  return block.slice(start, end).join("\n");
}

/**
 * One line with its YAML comment removed — a whole-line `#` comment, or a trailing ` # …`.
 * Quote-aware, so a `#` inside a quoted scalar is left alone.
 */
function stripComment(line: string): string {
  let quote: string | null = null;
  for (let i = 0; i < line.length; i++) {
    const c = line[i];
    if (quote !== null) {
      if (c === quote) quote = null;
    } else if (c === '"' || c === "'") {
      quote = c;
    } else if (c === "#" && (i === 0 || /\s/.test(line[i - 1]))) {
      return line.slice(0, i).trimEnd();
    }
  }
  return line;
}

/**
 * A whole service's text with COMMENTS AND BLANK LINES REMOVED. **Every assertion in this file goes
 * through this** — matching raw compose text is the defect class this file keeps re-acquiring.
 *
 * It is not cosmetic. The first cut matched the raw service text, so commenting out the two
 * PCI_MASTER_KEY lines left `PCI_MASTER_KEY: "${PCI_MASTER_KEY:-}"` present *verbatim inside a
 * comment* — every delivery assertion stayed green while `docker compose config` proved delivery
 * was 0. The second cut fixed only the `app` service's environment block, so the `logs` image pin
 * kept the same hole: a maintainer who bumps the tag and leaves the old pin commented above it —
 *
 *     # was: image: amir20/dozzle:v10.6.11@sha256:bc1e…
 *     image: amir20/dozzle:v10.7.0
 *
 * — still satisfied the digest regex while the service that mounts `/var/run/docker.sock` ran an
 * unpinned moving tag (`not.toContain("dozzle:latest")` misses it too; the tag isn't `:latest`).
 * A guard named after the bug that passes ON the bug is this repo's most-repeated defect; compose
 * does not read comments, so neither may we.
 */
function commentFree(service: string): string {
  return serviceSlice(service)
    .split("\n")
    .map(stripComment)
    .filter((l) => l.trim() !== "")
    .join("\n");
}

/** One service's `environment:` mapping, sliced out of the comment-free text. */
function envBlock(service: string): string {
  const lines = commentFree(service).split("\n");
  const start = lines.findIndex((l) => /^ {4}environment:\s*$/.test(l));
  if (start < 0) throw new Error(`docker-compose.yml service '${service}' has no environment: block`);
  let end = lines.length;
  for (let i = start + 1; i < lines.length; i++) {
    // Any key back at the service's own indent (`    ports:`, `    volumes:`) ends the block.
    if (/^ {4}\S/.test(lines[i])) {
      end = i;
      break;
    }
  }
  return lines.slice(start + 1, end).join("\n");
}

/** The env var names a service ACTUALLY delivers — parsed from the comment-free mapping only. */
function deliveredEnvNames(service: string): string[] {
  return [...envBlock(service).matchAll(/^ {6}([A-Z][A-Z0-9_]*):/gm)].map((m) => m[1]);
}

// Comment-free by construction: no assertion below can be satisfied by commented-out YAML.
const app = commentFree("app");
const appEnv = envBlock("app");
const appEnvNames = deliveredEnvNames("app");

describe("compose packaging: guards", () => {
  // If any of these ever fails, every assertion below it was about to test an empty string.
  it("the app slice is the real app service", () => {
    expect(app).toContain('image: "ghcr.io/getpostern/postern');
    expect(app).toContain("DATABASE_URL:");
  });

  it("the app environment block is real, and every surviving line is a live mapping — not a comment", () => {
    // The stripping guard. If a `#` line ever survives here, every delivery assertion below can be
    // satisfied by commented-out YAML, which compose ignores entirely.
    expect(appEnv).not.toBe("");
    expect(appEnv).not.toContain("#");
    for (const line of appEnv.split("\n")) {
      expect(line).toMatch(/^ {6}[A-Z][A-Z0-9_]*:/);
    }
    expect(appEnvNames).toContain("DATABASE_URL");
    expect(appEnvNames.length).toBeGreaterThanOrEqual(10);
  });

});

describe("compose packaging: env delivery (#97)", () => {
  it("every environment variable documented in .env.example is delivered to the app container", () => {
    // Derived from the file, never hardcoded: a hardcoded list is a fixture that can carry the same
    // wrong value as the code, and would keep passing when a NEW documented var goes undelivered.
    const documented = [
      ...new Set([...envExample.matchAll(/^#?\s*([A-Z][A-Z0-9_]*)=/gm)].map((m) => m[1])),
    ];
    // Sanity: the extraction actually found the documented knobs (an empty set would pass vacuously).
    expect(documented).toContain("DATABASE_URL");
    expect(documented).toContain("PCI_MASTER_KEY");
    expect(documented.length).toBeGreaterThanOrEqual(5);

    // Host-only variables, each here WITH the reason. These are read by DOCKER COMPOSE ITSELF on the
    // host — they configure the db service or a host-side port publish — and the gateway process
    // never reads any of them, so delivering them to the app container would be noise, not delivery.
    // Adding a name here is how a genuinely-undelivered var gets waved through, so the bar is: the
    // gateway's own code must not read it, in ANY form — see readByGateway, which checks the quoted
    // name too because the OAuth secrets are read through a computed key, not a dotted access.
    const hostOnly: string[] = [
      "POSTGRES_USER", // the db service's role — compose interpolates it into DATABASE_URL for the app
      "POSTGRES_PASSWORD", // ditto
      "POSTGRES_DB", // ditto
      "POSTGRES_HOST_PORT", // where Postgres is published on the HOST; the app reaches db:5432 regardless
      "DOZZLE_HOST_PORT", // where the opt-in log viewer is published on the HOST
    ];

    // hostOnly is an ESCAPE HATCH from the assertion below, so it needs its own gate — otherwise the
    // cheapest way to make this test pass is to add the undelivered name to the list, and #97 walks
    // straight back in wearing a green suite. The gate is the stated bar, mechanised: a name may only
    // sit here if the gateway's own code never reads it.
    const srcRead = readSrcTree();
    const wronglyWaved = hostOnly.filter((n) => readByGateway(n, srcRead));
    expect(wronglyWaved).toEqual([]);
    // Guards, both against a vacuous scan. The first proves the corpus is real; the next two prove
    // BOTH detection forms actually fire on this corpus — a dotted read and a computed-key read
    // whose name only ever appears as a string literal (PROVIDERS, src/oauth/providers.ts). Without
    // the third, the indirection hole could be reopened and nothing here would notice.
    expect(srcRead.length).toBeGreaterThan(50_000);
    expect(readByGateway("REST_ALLOWED_HOSTS", srcRead)).toBe(true); // process.env.REST_ALLOWED_HOSTS
    expect(readByGateway("MICROSOFT_OAUTH_CLIENT_SECRET", srcRead)).toBe(true); // quoted-only
    expect(srcRead).not.toContain("process.env.MICROSOFT_OAUTH_CLIENT_SECRET"); // …proving it IS quoted-only

    // Matched against the COMMENT-FREE mapping: a `# FOO: "${FOO:-}"` line delivers nothing.
    const undelivered = documented.filter((n) => !hostOnly.includes(n) && !appEnvNames.includes(n));
    expect(undelivered).toEqual([]);
  });

  it("the app service passes PCI_MASTER_KEY and PCI_MASTER_KEY_ID through compose interpolation", () => {
    // The `:-` default matters: without it compose ERRORS on an unset variable for some versions and
    // (worse) a hardcoded value here would ship one key to every user of this repo.
    // appEnv (comment-free, and scoped to the environment mapping): a `# PCI_MASTER_KEY: …` line
    // delivers nothing, and neither does one parked outside the environment block.
    expect(appEnv).toContain('PCI_MASTER_KEY: "${PCI_MASTER_KEY:-}"');
    expect(appEnv).toContain('PCI_MASTER_KEY_ID: "${PCI_MASTER_KEY_ID:-}"');
  });

  it(".env.example never puts a comment on a variable's own line — compose would deliver it AS the value", () => {
    // The exposure this unit created (#97 review, blocker 3): compose's dotenv parser strips a
    // trailing comment only when a VALUE precedes it, so `PCI_MASTER_KEY_ID=   # optional label`
    // uncommented is delivered as the LITERAL string "# optional label …" and every credential seals
    // under that key_id. The operator later tidies the line, the label moves, and the fail-closed
    // boot gate refuses to start on a vault whose key was never wrong. Comments go on their own line.
    const offenders = envExample
      .split("\n")
      .filter((l) => /^#?\s*[A-Z][A-Z0-9_]*=/.test(l))
      .filter((l) => l.slice(l.indexOf("=") + 1).includes("#"));
    expect(offenders).toEqual([]);
    // Guard: the filter actually saw variable lines (an empty file passes the assertion above).
    expect(envExample.split("\n").filter((l) => /^#?\s*[A-Z][A-Z0-9_]*=/.test(l)).length).toBeGreaterThanOrEqual(5);
  });

  it("the repo ships no dotenv dependency, so compose interpolation stays the only delivery path", () => {
    // Guards against "fixing" delivery by teaching the app to read .env while compose stays broken —
    // which would work on a dev box and still not deliver anything inside the container.
    expect(packageJson).not.toContain('"dotenv"');
  });
});

